        Hidden: ' hidden',
        Stale: ' (check: the other side has changed)',
        EndedMark: ' ENDED',
        ClosedMark: ' CLOSED',
        Joiner: ' | ',
        Day: 'Day ',
        Hash: '#',
        Span: '-#',
        Present: 'present: ',
        From: 'from #',
        Until: 'until #',
        NumberOpen: '[#',
        NumberClose: '] ',
        AnswerMarker: ' ANSWER: ',
        NormalForm: 'NFC',
        Apostrophe: "'",
        CommonWords: Object.freeze(['the', 'and', 'of']),
        ShortestAka: 3,
        ShortestWord: 3,
        CasedWord: 2,
        ShownScenes: 3,
        ShownNights: 3,
        NoSceneBefore: 1,
        NoLimit: Number.POSITIVE_INFINITY,
        BoundaryWidth: 2,
        Last: -1,

        /**
         * @return {RegExp}
         */
        get Apostrophes() {
            return /[’‘ʼ]/gu;
        },

        /**
         * @return {RegExp}
         */
        get Whitespace() {
            return /\s+/gu;
        },

        /**
         * @return {RegExp}
         */
        get Word() {
            return /[\p{L}\p{M}\p{N}]+/gu;
        },

        /**
         * @return {RegExp}
         */
        get WordBefore() {
            return /[\p{L}\p{M}\p{N}]$/u;
        },

        /**
         * @return {RegExp}
         */
        get WordAfter() {
            return /^[\p{L}\p{M}\p{N}]/u;
        },

