            const resolved = thread.closed.how;
            const how = resolved === settings.Nothing ? settings.Nothing : settings.Colon + resolved;
            closed.push(
                thread.id +
                    settings.Colon +
                    thread.text +
                    settings.CiteOpen +
                    thread.position +
                    settings.Closing +
                    settings.ClosedMark +
                    how +
                    settings.CiteOpen +
                    thread.closed.position +
                    settings.Closing,
            );
