        LastSuccess: 299,
        RoomsPath: '/v1/rooms/',
        SavedRoomsLimit: 20,
        MessagesPath: '/messages',
        PlotsPath: '/v1/plots/',
        RoomsSegment: '/rooms/',
        PersonaPath: '/user-personas/selected',
        NotFound: 404,
        NameSeparator: ': ',
        PlotIdPaths: Object.freeze([Object.freeze(['plotId']), Object.freeze(['plot', 'id'])]),
