            offer = await ScribeMuse.suggest({
                state: view.state,
                now: live.record.now,
                recent: view.messages.slice(-settings.Recent),
                exclude: [...excluded],
                ask: ScribeLive.asker(live, settings.Roles.Scribe, noted),
            });
